INSERT INTO content_blocks (key, value) VALUES ('hero', '{"en": {"eyebrow": "Est. 2022 · Jeddah", "brandLine": "ABH AUTO", "tagline": "Protection and Care, Refined", "subline": "Professional ceramic coatings, paint protection film, and precision detailing — delivered by private appointment.", "cta_primary": "Book an Appointment", "scroll": "Scroll", "cta_secondary": "Explore Services", "discover": "Discover More"}, "ar": {"eyebrow": "تأسست 2022 · جدة", "brandLine": "ABH AUTO", "tagline": "حماية وصيانة بمعايير عالمية", "subline": "سيراميك احترافي، أفلام حماية الطلاء، وتفاصيل دقيقة — جميع الخدمات بالموعد الخاص.", "cta_primary": "احجز موعدك", "scroll": "مرر لأسفل", "cta_secondary": "استعرض الخدمات", "discover": "اكتشف المزيد"}}'::jsonb)
