INSERT INTO content_blocks (key, value) VALUES ('banner', '{"en": {"highlight": "Limited Opening Offers", "title": "Grand Opening — Up to 40% Off", "copy": "To mark our opening, selected packages are available at special rates across ceramic coatings, paint protection film, and full-care services. Limited time, by appointment only.", "cta": "Reserve Now", "ends": "Offer Ends In", "badgeUp": "UP TO", "badgeOff": "OFF", "eyebrow": "GRAND OPENING"}, "ar": {"highlight": "عروض افتتاح محدودة", "title": "احتفال الافتتاح — حتى 40٪ خصم", "copy": "بمناسبة الافتتاح، نقدم باقات مختارة بأسعار خاصة على السيراميك، وأفلام الحماية، وخدمات العناية الكاملة. العرض لفترة محدودة وبالموعد الخاص فقط.", "cta": "احجز الآن", "ends": "ينتهي العرض خلال", "badgeUp": "حتى", "badgeOff": "خصم", "eyebrow": "الافتتاح الكبير"}}'::jsonb)
  ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO content_blocks (key, value) VALUES ('offers', '{"en": {"eyebrow": "SELECTED OFFERS", "title": "Signature Packages", "subtitle": "Practical, carefully built programs for owners who expect a premium result and a smooth experience.", "badge": "LIMITED", "items": [{"title": "Luxury Ceramic Suite", "copy": "Deep gloss, easier maintenance, and a refined finish delivered with expert application.", "discount": "-25%"}, {"title": "Summer Shield Program", "copy": "A smart choice for heat, UV exposure, and dust — with enhanced interior care.", "discount": "-18%"}, {"title": "Elite Membership", "copy": "Priority booking, dedicated follow-up, and year-round advisory support.", "discount": "VIP"}], "viewAll": "View All Offers", "campaign": "Limited Campaign", "navHome": "Home", "navOffers": "Offers", "subA": "Signature", "subItalic": "campaigns", "segCar": "Single car", "segFleet": "Fleet", "offersEyebrow": "THE PACKAGES", "offersTitle": "Three Tiers. One Standard.", "offersSub": "Choose the tier your car deserves. Tap any package to open its full details.", "from": "From", "currency": "SAR", "onRequest": "On request", "recommended": "Most chosen", "open": "Package details", "reserve": "Reserve package", "cmpEyebrow": "COMPARE PACKAGES", "inclH": "What''s included", "worksH": "How it works", "mClose": "Close", "ctaEyebrow": "INVITATION", "ctaLine": "Choose your package.", "ctaSub": "Leave the rest to us.", "ctaPrimary": "Book a consultation", "ctaSecondary": "Speak to an advisor", "detail": [{"name": "Summer Shield Program", "copy": "UV-rated ceramic + full interior conditioning for desert climates.", "lead": "Engineered for the harshness of the Gulf summer — protecting paint from UV, conditioning the cabin against heat, with a hydrophobic layer that keeps the car cleaner for longer.", "feats": ["UV-rated ceramic", "Full interior prep", "Heat protection", "One maintenance session"], "incl": ["UV ceramic layer, 3-year warranty", "Full interior deep-clean & wrap", "Leather & surface treatment", "Hydrophobic glass coating", "Full technical inspection", "Free maintenance session at 6 months"], "steps": [["Intake & assessment", "Paint and interior condition inspected and documented."], ["Preparation", "Detailed wash, decontamination, old wax removal."], ["Application", "UV-resistant ceramic layer + interior conditioning."], ["Delivery", "Final inspection under light + warranty card."]], "terms": "Limited-time offer. Prices start from the figure shown and vary by vehicle size and condition."}, {"name": "Diamond Ceramic Suite", "copy": "12-year nano-ceramic with optical clarity and a self-healing topcoat.", "lead": "The finest we offer. A 12-layer nano-ceramic system applied in a cleanroom — unmatched optical depth and protection documented for ten years.", "feats": ["12-layer nano-ceramic", "10-year warranty", "Self-healing topcoat", "Class-1000 cleanroom", "Multi-stage correction"], "incl": ["Multi-stage paint correction", "12 nano-ceramic layers", "Self-healing topcoat", "Class-1000 cleanroom application", "Independent UV rating", "10-year manufacturer warranty", "Documented dossier with the car", "Two annual maintenance sessions"], "steps": [["Diagnosis & documentation", "Every panel inspected under polarized light, state photographed."], ["Correction", "Scratches and swirls removed across three stages."], ["Application", "12 ceramic layers, 12-hour cure per coat."], ["Final inspection", "Reviewed under light, documented dossier delivered."]], "terms": "The most chosen among our clients. Prices start from the figure shown and are finalized after assessment."}, {"name": "Elite Membership", "copy": "Annual access to a private technician team, valet pickup and global insurance.", "lead": "Not a package — a relationship. Unlimited annual access to the atelier, a team dedicated to your cars, and a concierge that handles everything, wherever you are.", "feats": ["Dedicated technician team", "Valet pickup & delivery", "Global coverage", "Absolute booking priority", "Work insured"], "incl": ["Unlimited sessions per year", "Dedicated team for your collection", "Private valet pickup & delivery", "Direct  line, 24/7", "Absolute booking priority", "International coverage & pickup", "All work fully insured", "Invitations to private events"], "steps": [["Private conversation", "An introductory session to understand your collection."], ["Programming", "A bespoke annual plan designed per car."], ["Activation", "Your dedicated team and  are assigned, and service begins."], ["Stewardship", "Ongoing management and periodic reports per car."]], "terms": "Membership is by invitation and assessment. Value is set by collection size and scope of service."}], "cmp": {"tiers": ["Summer", "Diamond", "Elite"], "rows": [["Manufacturer warranty", "3 yrs", "10 yrs", "10 yrs+"], ["Ceramic layers", "—", "12", "Bespoke"], ["Cleanroom", "no", "yes", "yes"], ["Valet service", "no", "no", "yes"], ["Global coverage", "no", "no", "yes"], ["24/7  access", "no", "no", "yes"]]}, "save": "Save", "off": "Off", "allTitle": "The full collection", "all": [{"tag": "Seasonal", "title": "Summer Ceramic Shield", "copy": "UV-rated ceramic with hydrophobic glass — built for the Gulf summer.", "discount": "18% Off"}, {"tag": "Flagship", "title": "Diamond Protection Suite", "copy": "A twelve-layer nano-ceramic system applied in a class-1000 cleanroom.", "discount": "25% Off"}, {"tag": "Film", "title": "Full-Body Paint Film", "copy": "Bumper-to-bumper self-healing PPF, precision-cut and near invisible.", "discount": "15% Off"}, {"tag": "Bundle", "title": "Ceramic + Tint Bundle", "copy": "9H ceramic paired with IR-rejecting ceramic window film.", "discount": "20% Off"}, {"tag": "Interior", "title": "Cabin Revival", "copy": "Full interior steam, leather conditioning and ceramic fabric guard.", "discount": "12% Off"}, {"tag": "Wheels", "title": "Wheel & Caliper Ceramic", "copy": "Heat-resistant ceramic on wheel faces, barrels and calipers.", "discount": "22% Off"}]}, "ar": {"eyebrow": "عروض مختارة", "title": "باقات مميّزة", "subtitle": "برامج عملية ومدروسة لمالكي السيارات الذين يريدون نتيجة واضحة وخدمة راقية.", "badge": "محدود", "items": [{"title": "باقة السيراميك الفاخر", "copy": "حماية بلمعان عميق، ولمسة نهائية سهلة العناية، مع تنفيذ احترافي.", "discount": "-25٪"}, {"title": "برنامج درع الصيف", "copy": "حلول مناسبة للحرارة والأشعة فوق البنفسجية والغبار، مع عناية داخلية محسّنة.", "discount": "-18٪"}, {"title": "عضوية النخبة", "copy": "أولوية في الحجز، متابعة خاصة، وخدمة استشارية مخصصة على مدار العام.", "discount": "VIP"}], "viewAll": "عرض كل العروض", "campaign": "عرض محدود", "navHome": "الرئيسية", "navOffers": "العروض", "subA": "حملاتٌ", "subItalic": "موقّعة", "segCar": "سيارة واحدة", "segFleet": "أسطول", "offersEyebrow": "الباقات", "offersTitle": "ثلاث مراتب. معيار واحد.", "offersSub": "اختر المرتبة التي تليق بسيارتك. اضغط أي باقة لتفتح تفاصيلها الكاملة.", "from": "يبدأ من", "currency": "ر.س", "onRequest": "بالطلب", "recommended": "الأكثر اختياراً", "open": "تفاصيل الباقة", "reserve": "احجز الباقة", "cmpEyebrow": "مقارنة الباقات", "inclH": "ما تتضمّنه الباقة", "worksH": "كيف نعمل", "mClose": "إغلاق", "ctaEyebrow": "الدعوة", "ctaLine": "اختر باقتك.", "ctaSub": "ودع الباقي علينا.", "ctaPrimary": "احجز استشارة", "ctaSecondary": "تحدّث مع الفريق", "detail": [{"name": "برنامج درع الصيف", "copy": "سيراميك مقاوم للأشعة فوق البنفسجية وتهيئة كاملة للمقصورة في المناخات الصحراوية.", "lead": "برنامجٌ مصمّم لقسوة الصيف الخليجي — يحمي الطلاء من الأشعة، ويهيّئ المقصورة لتقاوم الحرارة، مع طبقة طاردة للماء تُبقي السيارة نظيفة لفترة أطول.", "feats": ["سيراميك مقاوم UV", "تهيئة كاملة للمقصورة", "حماية من الحرارة", "جلسة صيانة واحدة"], "incl": ["طبقة سيراميك UV بضمان ٣ سنوات", "تنظيف وتغليف كامل للمقصورة", "معالجة الجلد والأسطح", "طبقة طاردة للأمطار على الزجاج", "فحص فني شامل", "جلسة صيانة مجانية بعد ٦ أشهر"], "steps": [["الاستلام والتقييم", "فحص حالة الطلاء والمقصورة وتوثيقها."], ["التحضير", "غسيل تفصيلي وإزالة الملوّثات والتشميع القديم."], ["التطبيق", "طبقة السيراميك المقاومة للأشعة وتهيئة المقصورة."], ["التسليم", "فحص نهائي تحت الضوء وتسليم بطاقة الضمان."]], "terms": "العرض ساري لفترة محدودة. الأسعار تبدأ من القيمة المذكورة وتختلف حسب حجم السيارة وحالتها."}, {"name": "باقة سيراميك الألماس", "copy": "طبقة نانو سيراميك تدوم ١٢ عاماً مع نقاء بصري وطبقة ذاتية الإصلاح.", "lead": "أرفع ما نقدّمه. منظومة نانو سيراميك من ١٢ طبقة تُطبَّق في غرفة نظيفة، تمنح عمقاً بصرياً لا يضاهى وحماية موثّقة لعشر سنوات.", "feats": ["نانو سيراميك ١٢ طبقة", "ضمان ١٠ سنوات", "طبقة ذاتية الإصلاح", "غرفة نظيفة ١٠٠٠", "تصحيح متعدد المراحل"], "incl": ["تصحيح طلاء متعدد المراحل", "١٢ طبقة نانو سيراميك", "طبقة علوية ذاتية الإصلاح", "معالجة في غرفة نظيفة فئة ١٠٠٠", "تقييم UV مستقل", "ضمان مصنع ١٠ سنوات", "ملف موثّق يرافق السيارة", "جلستا صيانة سنوية"], "steps": [["التشخيص والتوثيق", "فحص كل لوحة تحت ضوء مستقطب وتصوير الحالة."], ["التصحيح", "إزالة الخدوش والدوامات على ثلاث مراحل."], ["التطبيق", "١٢ طبقة سيراميك بزمن تماسك ١٢ ساعة لكل طبقة."], ["الفحص النهائي", "مراجعة تحت الضوء وتسليم الملف الموثّق."]], "terms": "الأكثر اختياراً بين عملائنا. الأسعار تبدأ من القيمة المذكورة وتُحدّد نهائياً بعد المعاينة."}, {"name": "عضوية النخبة", "copy": "وصول سنوي إلى فريق فنّي خاص، خدمة فاليه واستلام عالمي وتأمين دولي.", "lead": "ليست باقة، بل علاقة. وصولٌ سنوي غير محدود إلى الأتيليه، بفريق مخصّص لسياراتك، وخدمة متابعة خاصة تتولّى كل شيء — أينما كنت.", "feats": ["فريق فني مخصّص", "استلام وتسليم فاليه", "تغطية دولية", "أولوية مطلقة في المواعيد", "تأمين على الأعمال"], "incl": ["عدد غير محدود من الجلسات سنوياً", "فريق فني مخصّص لمجموعتك", "استلام وتسليم فاليه خاص", "خط الالفريق المباشر ٢٤/٧", "أولوية مطلقة في الحجز", "تغطية واستلام دولي", "تأمين على جميع الأعمال", "دعوات لفعاليات خاصة"], "steps": [["محادثة خاصة", "جلسة تعارف لفهم مجموعتك واحتياجاتك."], ["وضع البرنامج", "تصميم خطة سنوية مخصّصة لكل سيارة."], ["التفعيل", "تخصيص الفريق والالفريق الخاص وبدء الخدمة."], ["المتابعة", "إدارة مستمرة وتقارير دورية عن كل سيارة."]], "terms": "العضوية بالدعوة والتقييم. تُحدّد القيمة حسب حجم المجموعة ونطاق الخدمة."}], "cmp": {"tiers": ["درع الصيف", "الألماس", "النخبة"], "rows": [["ضمان مصنع", "٣ سنوات", "١٠ سنوات", "١٠ سنوات+"], ["عدد الطبقات", "—", "١٢", "حسب الطلب"], ["غرفة نظيفة", "no", "yes", "yes"], ["خدمة فاليه", "no", "no", "yes"], ["تغطية دولية", "no", "no", "yes"], ["كونسيرج ٢٤/٧", "no", "no", "yes"]]}, "save": "وفّر", "off": "خصم", "allTitle": "كل العروض", "all": [{"tag": "موسمي", "title": "درع السيراميك الصيفي", "copy": "سيراميك مقاوم للأشعة فوق البنفسجية مع زجاج طارد للماء — لصيف الخليج.", "discount": "خصم 18٪"}, {"tag": "الأفخم", "title": "باقة حماية الألماس", "copy": "نظام نانو سيراميك من ١٢ طبقة يُطبَّق في غرفة نظيفة Class-1000.", "discount": "خصم 25٪"}, {"tag": "فيلم", "title": "حماية كاملة لطلاء الجسم", "copy": "فيلم PPF ذاتي الإصلاح من الصدام للصدام، مقصوص بدقة وشبه خفي.", "discount": "خصم 15٪"}, {"tag": "باقة", "title": "سيراميك + عازل", "copy": "سيراميك 9H مع عازل نوافذ سيراميك يصدّ الأشعة تحت الحمراء.", "discount": "خصم 20٪"}, {"tag": "داخلي", "title": "إنعاش المقصورة", "copy": "بخار كامل للداخلية، عناية بالجلد وحماية سيراميك للأقمشة.", "discount": "خصم 12٪"}, {"tag": "جنوط", "title": "سيراميك الجنوط والكاليبر", "copy": "سيراميك مقاوم للحرارة على واجهات الجنوط والبراميل والكاليبرات.", "discount": "خصم 22٪"}]}}'::jsonb)
  ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO content_blocks (key, value) VALUES ('services', '{"en": {"eyebrow": "OUR DISCIPLINE", "title": "Multiple Services. One Commitment to Excellence", "subtitle": "Every service is delivered in a controlled environment using carefully selected materials and tools.", "items": [{"slug": "ceramic", "title": "Nano Ceramic Coating", "blurb": "Clearer gloss. Easier upkeep. Long-lasting protection.", "long": "A multi-layer ceramic system applied in a controlled environment to enhance gloss, improve surface behavior, and simplify day-to-day care.", "benefits": ["Long-term protection", "Easier maintenance", "Clearer gloss", "Controlled application environment"]}, {"slug": "ppf", "title": "Paint Protection Film", "blurb": "Transparent defense against chips and daily wear.", "long": "Precision-cut transparent film designed to reduce the impact of road debris, light scratches, and everyday wear while keeping the finish visually clean.", "benefits": ["Custom-cut per vehicle", "Nearly invisible finish", "Resists light abrasion", "Clean surface appearance"]}, {"slug": "armor", "title": "Armored Protection", "blurb": "Advanced security solutions with careful integration.", "long": "Ballistic and engineered protection solutions for vehicles that require a higher level of security, delivered with attention to appearance and driving dynamics.", "benefits": ["Specialized security options", "Visually balanced integration", "Precise engineering", "Tailored consultation"]}, {"slug": "tracking", "title": "Smart Tracking Systems", "blurb": "Quiet monitoring with reliable alerts.", "long": "Advanced tracking systems that support monitoring and remote control, helping owners stay informed and confident in daily use and travel.", "benefits": ["Real-time alerts", "Remote control", "Low-profile installation", "Built for daily use"]}, {"slug": "security", "title": "Smart Security Systems", "blurb": "Safer access, smarter control.", "long": "Smart security upgrades such as biometric ignition, mobile control, and additional protection layers installed with care and without disturbing the cabin’s design.", "benefits": ["Biometric ignition", "Mobile control", "Additional protection", "Factory look preserved"]}, {"slug": "detailing", "title": "Luxury Detailing", "blurb": "A refined finish for exceptional cars.", "long": "Multi-stage paint correction, precise interior care, and finishing work that helps the vehicle feel as composed as the day it left the showroom.", "benefits": ["Multi-stage correction", "Interior care", "Refined finishing", "Measured results"]}], "open": "Open Service", "request": "Request This Service", "viewAll": "View All Services", "discover": "Discover"}, "ar": {"eyebrow": "تخصصنا", "title": "خدمات كثيرة ، معيار واحد.", "subtitle": "كل خدمة تُنفذ داخل بيئة مُنظَّمة وبأدوات ومواد مختارة بعناية.", "items": [{"slug": "ceramic", "title": "طلاء نانو سيراميك", "blurb": "لمعان أوضح. صيانة أسهل. حماية تدوم.", "long": "نظام طلاء سيراميك متعدد الطبقات يُطبّق داخل بيئة محكومة، بهدف تعزيز اللمعان، وتحسين مقاومة السطح، وتسهيل الغسيل اليومي.", "benefits": ["حماية طويلة الأمد", "سطح أسهل في التنظيف", "لمعان أوضح", "تنفيذ داخل بيئة محكمة"]}, {"slug": "ppf", "title": "أفلام حماية الطلاء", "blurb": "حماية شفافة ضد الخدوش والاصطدامات اليومية.", "long": "فيلم حماية شفاف يُقصّ بدقة لكل سيارة، ويُستخدم لتقليل أثر الحصى، والخدوش الدقيقة، وعوامل الطريق اليومية مع مظهر شبه غير مرئي.", "benefits": ["قصّ مخصص لكل سيارة", "حماية شبه غير مرئية", "مقاومة للخدوش الدقيقة", "ملمس وشكل نظيف"]}, {"slug": "armor", "title": "الحماية المدرعة", "blurb": "حلول أمان متقدمة بدمج احترافي.", "long": "نوفّر حلول حماية بالستية وهندسية للسيارات التي تتطلب مستوى أعلى من الأمان، مع مراعاة التناسق البصري وأداء السيارة.", "benefits": ["حلول أمان متخصصة", "دمج بصري متناسق", "تنفيذ هندسي دقيق", "استشارة حسب الاستخدام"]}, {"slug": "tracking", "title": "أنظمة تتبع ذكية", "blurb": "مراقبة هادئة مع تنبيهات موثوقة.", "long": "أنظمة تتبع متقدمة تدعم المراقبة والتحكم عن بُعد، وتساعد في تعزيز مستوى الأمان والاطمئنان على السيارة في الاستخدام اليومي والسفر.", "benefits": ["تنبيهات لحظية", "تحكم عن بُعد", "تركيب غير لافت", "مناسبة للاستخدام اليومي"]}, {"slug": "security", "title": "أنظمة أمان ذكية", "blurb": "دخول أكثر أمانًا وتجربة استخدام أذكى.", "long": "حلول أمان ذكية تشمل الإشعال بالبصمة، والتحكم عبر الهاتف، وخصائص حماية إضافية تُركب بعناية دون التأثير على أناقة المقصورة.", "benefits": ["إشعال بالبصمة", "تحكم عبر الهاتف", "حماية إضافية", "مظهر مصنع محفوظ"]}, {"slug": "detailing", "title": "تلميع وتفاصيل فاخرة", "blurb": "لمسة نهائية راقية تليق بالسيارات المميزة.", "long": "خدمات تلميع متعددة المراحل، وتصحيح للطلاء، وعناية داخلية دقيقة تمنح السيارة حضورًا أقرب لليوم الأول.", "benefits": ["تصحيح متعدد المراحل", "عناية داخلية دقيقة", "لمسة نهائية راقية", "نتيجة محسوبة"]}], "open": "عرض الخدمة", "request": "اطلب هذه الخدمة", "viewAll": "عرض كل الخدمات", "discover": "اكتشف"}}'::jsonb)
  ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO content_blocks (key, value) VALUES ('why', '{"en": {"eyebrow": "WHY ABH AUTO", "title": "Trust Before Hype", "subtitle": "We rely on hands-on experience, selected materials, and results you can see at delivery.", "items": [{"title": "Real Experience", "copy": "Daily hands-on work with a wide range of vehicles and expectations."}, {"title": "Precise Execution", "copy": "Each stage is reviewed carefully from preparation to handover."}, {"title": "Protection That Lasts", "copy": "Solutions designed to preserve the vehicle’s appearance over time."}, {"title": "Trusted Quality", "copy": "Carefully selected materials and consistent workmanship."}, {"title": "Detail Driven", "copy": "The real difference lives in the small details, and we treat them that way."}], "badge": "Inside the Workshop", "promise": "The ABH Promise", "indoor": "Indoor Installation", "warranty": "Manufacturer Warranty", "warrantyYears": "Years", "accredited": "Approved materials and methods"}, "ar": {"eyebrow": "لماذا ABH AUTO", "title": "الثقة قبل الكلام", "subtitle": "نعتمد على الخبرة العملية، والمواد المختارة، والنتيجة التي يمكن رؤيتها عند التسليم.", "items": [{"title": "خبرة واقعية", "copy": "عمل يومي مباشر مع سيارات مختلفة واحتياجات مختلفة."}, {"title": "تنفيذ دقيق", "copy": "كل مرحلة تُراجع بعناية من التحضير حتى التسليم."}, {"title": "حماية تدوم", "copy": "حلول مصممة للحفاظ على مظهر السيارة لأطول فترة ممكنة."}, {"title": "جودة موثوقة", "copy": "مواد مختارة بعناية ومعايير تنفيذ ثابتة."}, {"title": "اهتمام بالتفاصيل", "copy": "الفروق الحقيقية تظهر في التفاصيل الصغيرة، ونحن نعتني بها."}], "badge": "داخل الورشة", "promise": "وعد ABH", "indoor": "تركيب داخلي", "warranty": "ضمان من المصنّع", "warrantyYears": "سنوات", "accredited": "مواد وتقنيات معتمدة"}}'::jsonb)
  ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO content_blocks (key, value) VALUES ('projects', '{"en": {"eyebrow": "RECENT WORK", "title": "Selected Workshop Projects", "subtitle": "A curated selection of recent work that reflects our level of execution.", "viewAll": "View Archive", "chapter": "Chapter", "metaCars": "Cars entrusted", "metaEst": "Established", "metaProjects": "Published projects", "archiveEyebrow": "THE GALLERY", "archiveTitle": "Selected Workshop Work", "archiveSub": "A curated set of recently completed projects. Tap any card to open its dossier.", "open": "Open project", "ctaEyebrow": "INVITATION", "ctaLine": "Bring us the car.", "ctaSub": "We will do the rest.", "ctaPrimary": "Reserve a private viewing", "ctaSecondary": "Speak to an advisor", "mChapter": "Chapter", "mBefore": "Before", "mAfter": "After", "mBeforeCap": "State on arrival", "mAfterCap": "After completion", "mClose": "Close", "mLead": "It arrived with paint worn thin by the years. It left with new optical depth and protection honored in writing. This is what happened between the two doors.", "mSpecsH": "Specification", "mWorkH": "What happened in the atelier", "mView": "Reserve a project like this", "mSpecs": [["Duration", "240 hrs"], ["Layers", "12"], ["Warranty", "10 yrs"], ["Bay", "Private"]], "mSteps": [["Diagnosis & documentation", "Every panel inspected under polarized light; the initial state fully photographed."], ["Multi-stage correction", "Micro-scratches and swirls removed across three measured stages."], ["Nano-ceramic application", "12 layers in a cleanroom, with a 12-hour cure per coat."], ["Final inspection", "Reviewed under light; the documented dossier delivered with the car."]]}, "ar": {"eyebrow": "أعمال حديثة", "title": "نماذج من مشاريعنا", "subtitle": "مجموعة مختارة من الأعمال المنجزة مؤخرًا لتوضيح مستوى التنفيذ.", "viewAll": "عرض الأرشيف", "chapter": "الفصل", "metaCars": "سيارة في عهدتنا", "metaEst": "سنة التأسيس", "metaProjects": "مشروع منشور", "archiveEyebrow": "المعرض", "archiveTitle": "مختارات من أعمالنا", "archiveSub": "مجموعة منتقاة من المشاريع المنجزة حديثاً. اضغط أي بطاقة لتفتح ملف المشروع.", "open": "عرض المشروع", "ctaEyebrow": "الدعوة", "ctaLine": "أحضر لنا السيارة.", "ctaSub": "وسنتولّى الباقي.", "ctaPrimary": "احجز معاينة خاصة", "ctaSecondary": "تحدّث مع الفريق", "mChapter": "الفصل", "mBefore": "قبل", "mAfter": "بعد", "mBeforeCap": "الحالة عند الوصول", "mAfterCap": "بعد إتمام العمل", "mClose": "إغلاق", "mLead": "دخلت السيارة الغرفة بطبقة طلاء أنهكتها السنوات. خرجت بعمق بصري جديد، وحماية موثّقة كتابياً. هذا ملخّص ما جرى بين البابين.", "mSpecsH": "المواصفات", "mWorkH": "ما تمّ في الورشة", "mView": "احجز مثل هذا", "mSpecs": [["المدة", "٢٤٠ ساعة"], ["الطبقات", "١٢"], ["الضمان", "١٠ سنوات"], ["الورشة", "خاصة"]], "mSteps": [["تشخيص وتوثيق", "فحص كل لوحة تحت ضوء مستقطب، وتصوير الحالة الأولية بالكامل."], ["تصحيح متعدد المراحل", "إزالة الخدوش الدقيقة والدوامات على ثلاث مراحل بالغرام."], ["تطبيق النانو سيراميك", "١٢ طبقة في غرفة نظيفة، بزمن تماسك ١٢ ساعة لكل طبقة."], ["الفحص النهائي", "مراجعة تحت الضوء، وتسليم الملف الموثّق مع السيارة."]]}}'::jsonb)
  ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO content_blocks (key, value) VALUES ('testimonials', '{"en": {"eyebrow": "CLIENT FEEDBACK", "title": "From Owners We’re Proud to Serve", "subtitle": "Selected words from clients who experienced the service and recommend it with confidence."}, "ar": {"eyebrow": "آراء العملاء", "title": "من مالكي السيارات الذين نعتز بخدمتهم", "subtitle": "كلمات مختارة من عملاء جربوا الخدمة ويرشحونها بثقة."}}'::jsonb)
  ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO content_blocks (key, value) VALUES ('faq', '{"en": {"eyebrow": "FREQUENTLY ASKED", "title": "Common Questions", "items": [{"q": "What warranty do you offer?", "a": "Warranty length depends on the service and package, and we confirm it in writing before work begins."}, {"q": "How long does ceramic coating last?", "a": "That depends on the package, the way the car is used, and how well post-installation care is followed."}, {"q": "How long does the work take?", "a": "Timing varies by service type and project scope, and we confirm the schedule before booking."}, {"q": "Does the car need special care after installation?", "a": "We provide simple, clear aftercare guidance to help preserve the result."}, {"q": "How is pricing determined?", "a": "Pricing depends on the vehicle, the scope of work, and the selected package, all discussed in advance."}, {"q": "Do you offer pickup and delivery?", "a": "Yes — pickup, delivery, and special scheduling are available by arrangement."}], "subtitle": "Quick answers to the most common questions about services, warranty, and scheduling."}, "ar": {"eyebrow": "الأسئلة الشائعة", "title": "أسئلة متكررة", "items": [{"q": "ما نوع الضمان الذي تقدمونه؟", "a": "تختلف مدة الضمان حسب الخدمة والباقة، ونوضحها كتابةً قبل البدء."}, {"q": "كم تدوم طبقة السيراميك؟", "a": "يعتمد ذلك على نوع الباقة، وطريقة الاستخدام، والالتزام بالتعليمات بعد التركيب."}, {"q": "كم يستغرق التنفيذ؟", "a": "تختلف المدة حسب حجم العمل ونوع الخدمة، ونحددها لك قبل الحجز."}, {"q": "هل تحتاج السيارة لعناية خاصة بعد التركيب؟", "a": "نقدم لك تعليمات بسيطة وواضحة للعناية بعد التسليم للحفاظ على أفضل نتيجة."}, {"q": "كيف يتم تسعير الخدمات؟", "a": "السعر يعتمد على نوع السيارة، ونطاق العمل، والحزمة المطلوبة، ويتم توضيحه مسبقًا."}, {"q": "هل توجد خدمة استلام وتسليم؟", "a": "نعم، تتوفر خدمة استلام وتسليم وترتيب خاص حسب المواعيد."}], "subtitle": "إجابات سريعة على أكثر الأسئلة شيوعًا حول الخدمات والضمان والمواعيد."}}'::jsonb)
  ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO content_blocks (key, value) VALUES ('cta', '{"en": {"eyebrow": "GET STARTED", "title_a": "Your Vehicle", "title_b": "Deserves Better", "title": "Your Vehicle Deserves Better", "primary": "Book a Consultation", "secondary": "Speak to an Advisor", "advisor": "or speak to an advisor"}, "ar": {"eyebrow": "ابدأ الآن", "title_a": "سيارتك", "title_b": "تستحق الأفضل", "title": "سيارتك تستحق الأفضل", "primary": "احجز استشارة", "secondary": "تحدث مع الفريق", "advisor": "أو تحدث مع الفريق"}}'::jsonb)
