INSERT INTO content_blocks (key, value) VALUES ('footer', '{"en": {"tagline": "ABH AUTO — a specialized centre for luxury automotive protection through ceramic coatings, paint protection film, security solutions, and precision detailing.", "explore": "Explore", "company": "Company", "contact": "Contact", "hours": "By appointment only. Sunday through Thursday, 9:00 to 22:00 Saudi time. Saturdays by special arrangement.", "hoursValue": "Sun – Thu · 9:00 – 22:00", "subscribe": "Subscribe to the workshop journal", "subscribePlaceholder": "Your email address", "subscribeButton": "Subscribe", "rights": "All rights reserved.", "privacy": "Privacy", "terms": "Terms", "newsletterEyebrow": "Workshop Journal", "newsletterTitle": "Selected notes from the workshop, four times a year.", "newsletterCopy": "New materials, behind-the-scenes updates, and private invitations to limited appointments. No noise.", "newsletterDisclaimer": "By subscribing, you agree to our privacy policy.", "brandCopy": "A specialized centre for protecting and preserving standout vehicles, with ceramic, paint protection, security, and detailing programmes delivered with the discretion the car deserves.", "atelier": "Workshop", "phone": "Phone", "email": "Email", "connect": "Connect"}, "ar": {"tagline": "ABH AUTO — مركز متخصص في حماية السيارات الفاخرة عبر السيراميك، وأفلام حماية الطلاء، والحلول الأمنية، والتفاصيل الدقيقة.", "explore": "استكشف", "company": "الشركة", "contact": "تواصل", "hours": "بالموعد فقط. من الأحد إلى الخميس، من 9:00 إلى 22:00 بتوقيت السعودية. السبت بترتيب خاص.", "hoursValue": "الأحد – الخميس · 9:00 – 22:00", "subscribe": "اشترك في نشرة الورشة", "subscribePlaceholder": "بريدك الإلكتروني", "subscribeButton": "اشترك", "rights": "جميع الحقوق محفوظة.", "privacy": "الخصوصية", "terms": "الشروط", "newsletterEyebrow": "يوميات الورشة", "newsletterTitle": "رسائل مختارة من الورشة، أربع مرات في السنة.", "newsletterCopy": "أخبار المواد الجديدة، لمحات من الكواليس، ودعوات خاصة لمواعيد محدودة. بدون إزعاج.", "newsletterDisclaimer": "بالاشتراك أنت توافق على سياسة الخصوصية.", "brandCopy": "مركز متخصص في حماية وصون السيارات المميزة، مع برامج سيراميك وأفلام حماية وحلول أمان وتفاصيل دقيقة تُقدَّم بالخصوصية التي تستحقها السيارة.", "atelier": "الورشة", "phone": "هاتف", "email": "بريد", "connect": "تواصل"}}'::jsonb)
