INSERT INTO content_blocks (key, value) VALUES ('about', '{"en": {"meta": {"title": "About", "description": "ABH Auto — a workshop built around quiet discipline, measured execution, and careful handover."}, "obsession": {"chapter": "01", "label": "The Obsession", "line1": "We are not", "line2": "in the race", "line3": "for speed.", "line4": "We are in the", "line5": "race for right.", "footnote": "Three years. One standard. No compromise."}, "closeup": {"chapter": "02", "label": "Close-Up", "intro": "Look closer.", "frames": [{"tag": "0.0001 mm", "title": "The Layer", "copy": "A finely applied layer, inspected carefully before handover."}, {"tag": "12 hours", "title": "The Cure", "copy": "We allow the material the time it needs to settle properly."}, {"tag": "9H", "title": "The Bond", "copy": "A refined surface built for better resistance and clearer gloss."}, {"tag": "10 years", "title": "The Promise", "copy": "Written warranty according to the selected service and terms."}]}, "hand": {"chapter": "03", "label": "The Hand", "title": "One pair of hands.", "subtitle": "Every car.", "body": "We give each vehicle the time it deserves, with a small team focused on detail and consistency.", "name": "Abdullah Bin Hamad", "role": "Founder · Lead Technician"}, "standard": {"chapter": "04", "label": "The Standard", "intro": "Three rules.", "outro": "We do not accept work that misses them.", "rules": [{"n": "01", "rule": "Nothing is rushed.", "expand": "Every stage gets the time it needs to reach the right result."}, {"n": "02", "rule": "Nothing is hidden.", "expand": "The key steps are reviewed and the scope is explained before handover."}, {"n": "03", "rule": "Nothing is approximate.", "expand": "Preparation, measurement, and execution follow a clear method."}]}, "room": {"chapter": "05", "label": "The Room", "intro": "The environment is part of the result.", "body": "Clean air, proper light, and controlled temperature make a real difference in workmanship.", "specs": [{"k": "Air", "v": "Filtered"}, {"k": "Light", "v": "5500K"}, {"k": "Temp", "v": "22°C ± 1"}, {"k": "Bays", "v": "Private"}]}, "remains": {"chapter": "06", "label": "What Remains", "intro": "After years of work, what remains is the quality of execution.", "items": [{"v": "400", "unit": "+", "k": "Vehicles entrusted to us"}, {"v": "3", "unit": "yrs", "k": "Of continuous work"}, {"v": "0", "unit": "", "k": "Cars we regret"}, {"v": "1", "unit": "", "k": "Standard from day one"}]}, "invitation": {"chapter": "07", "label": "Invitation", "line": "Bring us the car.", "sub": "We will do the rest.", "cta": "Reserve a Private Viewing"}}, "ar": {"meta": {"title": "من نحن", "description": "ABH Auto — قصة ورشة تعمل بهدوء، وتُسلّم سيارات تُعامل بعناية شديدة."}, "obsession": {"chapter": "٠١", "label": "الهوس بالجودة", "line1": "لسنا في", "line2": "سباق", "line3": "السرعة.", "line4": "نحن في", "line5": "سباق الدقة.", "footnote": "ثلاث سنوات. معيار واحد. لا تنازل."}, "closeup": {"chapter": "٠٢", "label": "عن قرب", "intro": "انظر إلى التفاصيل.", "frames": [{"tag": "٠.٠٠٠١ مم", "title": "الطبقة", "copy": "طبقة دقيقة للغاية تُطبّق يدويًا وتُفحص بعناية قبل التسليم."}, {"tag": "١٢ ساعة", "title": "الاستقرار", "copy": "نمنح المواد الوقت الذي تحتاجه للوصول إلى أفضل نتيجة."}, {"tag": "9H", "title": "الترابط", "copy": "سطح محسّن للمقاومة والوضوح البصري وسهولة العناية."}, {"tag": "١٠ سنوات", "title": "الوعد", "copy": "ضمان مكتوب وفق الخدمة المختارة وشروطها."}]}, "hand": {"chapter": "٠٣", "label": "اليد", "title": "يد واحدة.", "subtitle": "لكل سيارة.", "body": "نمنح كل سيارة وقتها الكامل، ويُشرف على العمل فريق صغير يعرف قيمة التفاصيل.", "name": "عبدالله بن حمد", "role": "المؤسس · الفني الرئيسي"}, "standard": {"chapter": "٠٤", "label": "المعيار", "intro": "ثلاث قواعد.", "outro": "ولا نقبل ما لا يطابقها.", "rules": [{"n": "٠١", "rule": "لا شيء يُستعجل.", "expand": "نمنح كل مرحلة وقتها المناسب حتى نصل إلى النتيجة المطلوبة."}, {"n": "٠٢", "rule": "لا شيء يُخفى.", "expand": "تتم مراجعة الخطوات الأساسية وتوضيح نطاق العمل قبل التسليم."}, {"n": "٠٣", "rule": "لا شيء تقريبي.", "expand": "التجهيز والقياس والتنفيذ تتم بمنهجية واضحة ودقيقة."}]}, "room": {"chapter": "٠٥", "label": "الغرفة", "intro": "المكان جزء من النتيجة.", "body": "البيئة النظيفة، والضوء المناسب، ودرجة الحرارة المضبوطة تصنع فرقًا حقيقيًا في جودة العمل.", "specs": [{"k": "الهواء", "v": "مُرشَّح"}, {"k": "الضوء", "v": "٥٥٠٠ كلفن"}, {"k": "الحرارة", "v": "٢٢° ± ١"}, {"k": "المساحات", "v": "خاصة"}]}, "remains": {"chapter": "٠٦", "label": "ما يبقى", "intro": "بعد سنوات من العمل، يبقى أثر التنفيذ الجيد.", "items": [{"v": "٤٠٠", "unit": "+", "k": "سيارة في عهدتنا"}, {"v": "٣", "unit": "سنوات", "k": "من العمل المتواصل"}, {"v": "٠", "unit": "", "k": "سيارة نأسف عليها"}, {"v": "١", "unit": "", "k": "معيار منذ البداية"}]}, "invitation": {"chapter": "٠٧", "label": "الدعوة", "line": "أحضر لنا السيارة.", "sub": "ونتكفل بالباقي.", "cta": "احجز معاينة خاصة"}}}'::jsonb)
  ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO content_blocks (key, value) VALUES ('contact', '{"en": {"meta": {"title": "Contact", "description": "Write to the atelier in Jeddah. By private appointment only."}, "overture": {"eyebrow": "WRITE TO THE ATELIER", "title_a": "Start a", "title_b": "private conversation.", "subtitle": "Every message is read carefully by our team and answered during business hours.", "statusOpen": "Atelier open", "statusClosed": "Atelier closed", "scrollPrompt": "Compose"}, "compose": {"chapter": "01", "label": "THE LETTER", "title": "Fill in the details.", "subtitle": "A simple letter instead of a long form.", "letterTitle": "A letter from", "letterDate": "Today", "sentence1_a": "My name is", "sentence1_b": "and I would like to", "sentence1_c": "regarding my", "sentence1_d": ",", "sentence2_a": "You can reach me at", "sentence2_b": "or on", "sentence2_c": ".", "messageLabel": "What I would like to say", "messagePlaceholder": "Write your message here…", "placeholders": {"name": "your name", "intent": "what you would like to do", "vehicle": "your vehicle", "email": "your email", "phone": "your phone (optional)"}, "intentOptions": ["book a private viewing", "start a protection project", "speak with the advisor", "ask about press & partnerships"], "footer": "Sincerely,", "consent": "I agree that ABH Auto may store this message to respond to me.", "send": "Send Message", "sending": "Preparing the message…", "successTitle": "Your message has been sent.", "successCopy": "Our team will get back to you within four hours.", "successAction": "Write another", "errors": {"nameRequired": "Please enter your name.", "intentRequired": "Please choose a purpose.", "emailRequired": "We need an email to reply.", "emailInvalid": "The email address looks incomplete.", "messageRequired": "Please write a few words.", "consentRequired": "Please confirm consent."}}, "channels": {"eyebrow": "OR REACH US DIRECTLY", "title": "Three doors.", "subtitle": "Each one leads to the same atelier.", "items": [{"tag": "01", "label": "VISIT", "title": "By appointment", "copy": "Private visits are arranged in advance.", "value": "Book a visit", "subline": "Atelier I · Jeddah", "action": "form"}, {"tag": "02", "label": "CALL", "title": "Direct telephone", "copy": "A direct line to reception.", "value": "+966 12 000 0000", "subline": "9:00 – 22:00 AST", "action": "tel"}, {"tag": "03", "label": "MESSAGE", "title": "WhatsApp", "copy": "For quick questions and photos.", "value": "+966 50 000 0000", "subline": "Replies within the hour", "action": "whatsapp"}]}, "location": {"eyebrow": "FIND THE ATELIER", "title_a": "Jeddah · ", "title_b": "Al-Faisaliyah", "subtitle": "On the Red Sea coast. By appointment only.", "address": ["ABH Auto · Atelier I", "Al-Faisaliyah District", "Jeddah 23445", "Kingdom of Saudi Arabia"], "directionsCta": "Open in Google Maps", "phoneLabel": "Phone", "phone": "+966 12 000 0000", "emailLabel": "Email", "email": "concierge@abh-auto.example", "coordinatesLabel": "Coordinates"}, "closing": {"eyebrow": "BEHIND THE DOOR", "title_a": "Step inside", "title_b": "the atelier.", "subtitle": "Private bays. Filtered air. One vehicle at a time.", "hoursTitle": "Hours", "todayBadge": "Today", "timezone": "Jeddah · AST", "hoursRows": [{"days": "Sunday — Thursday", "hours": "9:00 — 22:00"}, {"days": "Friday", "hours": "Closed"}, {"days": "Saturday", "hours": "By arrangement"}]}}, "ar": {"meta": {"title": "تواصل معنا", "description": "راسل الأتيليه في جدة. بالمواعيد الخاصة فقط."}, "overture": {"eyebrow": "اكتب إلى الأتيليه", "title_a": "ابدأ", "title_b": "محادثة خاصة.", "subtitle": "يقرأ فريقنا الرسائل بعناية ويرد خلال ساعات العمل.", "statusOpen": "الأتيليه مفتوح", "statusClosed": "الأتيليه مغلق", "scrollPrompt": "اكتب رسالتك"}, "compose": {"chapter": "٠١", "label": "الرسالة", "title": "املأ بياناتك.", "subtitle": "رسالة بسيطة بدل النماذج الطويلة.", "letterTitle": "رسالة من", "letterDate": "اليوم", "sentence1_a": "اسمي", "sentence1_b": "وأرغب في", "sentence1_c": "بخصوص سي