INSERT INTO content_blocks (key, value) VALUES ('booking', '{"en": {"cats": {"packages": "Packages", "ceramic": "Nano Ceramic", "ppf": "Paint Film", "thermal": "Heat & Tint", "protection": "Protection", "addons": "Add-ons"}, "svc": {"pkg_diamond": {"name": "Diamond Suite", "desc": "Our flagship 12-layer nano-ceramic system applied in a class-1000 cleanroom."}, "pkg_summer": {"name": "Summer Shield", "desc": "UV-rated ceramic and full cabin conditioning, engineered for desert climates."}, "pkg_elite": {"name": "Elite Membership", "desc": "Unlimited annual access, a dedicated team, valet and 24/7  support."}, "cer_9h": {"name": "9H Nano Ceramic", "desc": "9H hardness ceramic for lasting depth of gloss and hydrophobic behaviour."}, "cer_graphene": {"name": "Graphene Ceramic", "desc": "Graphene-infused coating with superior heat dissipation and water sheeting."}, "cer_wheel": {"name": "Wheel & Caliper Ceramic", "desc": "Heat-resistant ceramic on wheel faces, barrels and calipers."}, "ppf_full": {"name": "Full-Body PPF", "desc": "Bumper-to-bumper precision-cut film, self-healing and near-invisible."}, "ppf_track": {"name": "Track Pack PPF", "desc": "High-impact zones — front end, rockers, mirrors — shielded for the road."}, "ppf_partial": {"name": "Partial Front PPF", "desc": "Hood, fenders and bumper protection against stone chips."}, "tint_ceramic": {"name": "Ceramic Window Tint", "desc": "IR-rejecting ceramic tint that cuts cabin heat without going dark."}, "tint_windshield": {"name": "Windshield Heat Film", "desc": "Optically clear heat-rejection film for the windshield."}, "prot_armor": {"name": "Ballistic Armoring", "desc": "Engineered ballistic protection with balanced weight and discretion."}, "prot_tracking": {"name": "Smart Tracking", "desc": "Low-profile GPS tracking with geofencing and instant alerts."}, "prot_security": {"name": "Smart Security", "desc": "Biometric ignition and app control with factory-clean integration."}, "add_detail": {"name": "Full Detai